import{_ as e,o as t,c as s,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const i="/assets/c5d35f7c9a7d2734-20261015000315-rplv6v9.BcDrgHDo.png",o="/assets/56a71c5a8f9e783b-20261015000315-2egb9ww.wj9dhS50.png",l="/assets/image-20261120173608-5e8yuo7.CflUszq_.png",n="/assets/b7b5f65fdeb3b57f-20261015000315-d1qbnvg.DMfiAQhd.png",c="/assets/d4cbfbf414768810-20261015000315-nr5eyp8.OtQ8LD-H.png",d="/assets/382d21859f79ed33-20261015000315-ipp65is.Ct5sgvKg.png",_="/assets/2b5b16380b938444-20261015000315-vt21y2u.D4bEIZ-v.png",p="/assets/f3e86cc996a2e34a-20261015000315-8lylhvv.CustA8Bl.png",q=JSON.parse('{"title":"安装说明","description":"","frontmatter":{"title":"安装说明","date":"2026-11-20T09:33:43.000Z","lastmod":"2026-11-20T09:45:15.000Z"},"headers":[],"relativePath":"guide/1016.md","filePath":"guide/EntisMAXIV/EntisMaxIV帮助文档/安装卸载说明/EntisMax软件安装/安装说明.md"}'),h={name:"guide/1016.md"};function m(u,a,g,b,S,f){return t(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="安装说明" tabindex="-1">安装说明 <a class="header-anchor" href="#安装说明" aria-label="Permalink to &quot;安装说明&quot;">​</a></h1><h2 id="主程序的安装过程" tabindex="-1">主程序的安装过程 <a class="header-anchor" href="#主程序的安装过程" aria-label="Permalink to &quot;主程序的安装过程&quot;">​</a></h2><hr><h4 id="_1-双击执行entismax安装包中的安装文件-名称格式为entismax-版本号-install-exe" tabindex="-1">1:双击执行EntisMax安装包中的安装文件,名称格式为EntisMAX[版本号]_Install.exe <a class="header-anchor" href="#_1-双击执行entismax安装包中的安装文件-名称格式为entismax-版本号-install-exe" aria-label="Permalink to &quot;1:双击执行EntisMax安装包中的安装文件,名称格式为EntisMAX[版本号]\\_Install.exe&quot;">​</a></h4><ul><li>如果已经安装了兼容的旧版本,则运行新版本安装文件会执行升级打补丁的功能</li></ul><h4 id="_2-如果弹出以下界面-表示可以正常安装-请点击下一步继续。" tabindex="-1">2:如果弹出以下界面，表示可以正常安装，请点击下一步继续。 <a class="header-anchor" href="#_2-如果弹出以下界面-表示可以正常安装-请点击下一步继续。" aria-label="Permalink to &quot;2:如果弹出以下界面，表示可以正常安装，请点击下一步继续。&quot;">​</a></h4><p><img src="'+i+'" alt=""></p><h4 id="_3-你可以自定义安装路径和其他选项-推荐保持默认-直接点击下一步" tabindex="-1">3:你可以自定义安装路径和其他选项，推荐保持默认，直接点击下一步 <a class="header-anchor" href="#_3-你可以自定义安装路径和其他选项-推荐保持默认-直接点击下一步" aria-label="Permalink to &quot;3:你可以自定义安装路径和其他选项，推荐保持默认，直接点击下一步&quot;">​</a></h4><p><img src="'+o+'" alt=""></p><h4 id="_4-选择安装路径后-下一步是附加任务。除了是否创建桌面快捷方式-还有一项" tabindex="-1">4:选择安装路径后，下一步是附加任务。除了是否创建桌面快捷方式，还有一项： <a class="header-anchor" href="#_4-选择安装路径后-下一步是附加任务。除了是否创建桌面快捷方式-还有一项" aria-label="Permalink to &quot;4:选择安装路径后，下一步是附加任务。除了是否创建桌面快捷方式，还有一项：&quot;">​</a></h4><p><img src="'+l+'" alt="image"></p><p><strong>是否按照默认配置自动安装SqlServer2017数据库</strong></p><p><strong>这一项默认不勾选。</strong></p><ul><li>不勾选：只安装主程序，不安装、不改动数据库。本机已经有可用的 SQL Server 时，保持不勾选即可。</li><li>勾选：主程序文件安装完成后，再按默认配置安装或配置 SQL Server 2017 Express。这一步可能需要几分钟，安装过程中请不要关闭窗口。</li></ul><p><strong>勾选后的默认配置如下：</strong></p><ul><li>实例名：<code>SQLEXPRESS</code></li><li>启用 SQL 身份验证，sa 密码为w****g( 常用密码)</li><li>启用 TCP协议通道</li><li>SQL Server Browser 设为自动启动</li><li>当前安装用户加入 SQL 管理员</li><li>防火墙放行该实例，并放行 SQL Browser 使用的 UDP 1434 端口</li><li>为程序目录下的 <code>Database</code> 文件夹授予 SQL 服务账户访问权限</li></ul><p>如果本机已经安装了 <code>SQLEXPRESS</code> 实例，不会重复安装，只按上面的配置处理。</p><p>安装程序优先使用与主程序安装包放在同一目录的 <code>SQLEXPR_x64_CHS.exe</code>。找不到这个文件时，会提示手动选择 SQL Server Express 安装包。取消选择则跳过数据库安装，主程序本身仍然安装完成。</p><p>数据库安装未完成时，会提示退出码，并请查看 <code>C:\\Program Files\\Microsoft SQL Server\\140\\Setup Bootstrap\\Log</code>。若提示需要重新启动计算机，请先重启，再使用数据库。</p><h4 id="_5-看到此界面-您可以开始安装了-请点击下一步。如果上一步勾选了自动安装数据库-此页-附加任务-中会列出该项。" tabindex="-1">5:看到此界面，您可以开始安装了，请点击下一步。如果上一步勾选了自动安装数据库，此页“附加任务”中会列出该项。 <a class="header-anchor" href="#_5-看到此界面-您可以开始安装了-请点击下一步。如果上一步勾选了自动安装数据库-此页-附加任务-中会列出该项。" aria-label="Permalink to &quot;5:看到此界面，您可以开始安装了，请点击下一步。如果上一步勾选了自动安装数据库，此页“附加任务”中会列出该项。&quot;">​</a></h4><p><img src="'+n+'" alt=""></p><h4 id="_6-正在安装-请稍待" tabindex="-1">6:正在安装，请稍待... <a class="header-anchor" href="#_6-正在安装-请稍待" aria-label="Permalink to &quot;6:正在安装，请稍待...&quot;">​</a></h4><p><img src="'+c+'" alt=""></p><h4 id="_7-看到此窗体-表明安装已成功完成-请点击关闭按钮即可" tabindex="-1">7:看到此窗体，表明安装已成功完成，请点击关闭按钮即可 <a class="header-anchor" href="#_7-看到此窗体-表明安装已成功完成-请点击关闭按钮即可" aria-label="Permalink to &quot;7:看到此窗体，表明安装已成功完成，请点击关闭按钮即可&quot;">​</a></h4><p><img src="'+d+'" alt=""></p><h4 id="_8-安装完成以后-会在桌面和开始菜单分别生成快捷方式-您可以点击运行程序。" tabindex="-1">8:安装完成以后，会在桌面和开始菜单分别生成快捷方式，您可以点击运行程序。 <a class="header-anchor" href="#_8-安装完成以后-会在桌面和开始菜单分别生成快捷方式-您可以点击运行程序。" aria-label="Permalink to &quot;8:安装完成以后，会在桌面和开始菜单分别生成快捷方式，您可以点击运行程序。&quot;">​</a></h4><p><img src="'+_+'" alt=""><img src="'+p+'" alt=""></p>',27)])])}const P=e(h,[["render",m]]);export{q as __pageData,P as default};
